// Coast and waterways sampled from the owner-supplied map. Distances in metres.
const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0)),grid=new Int16Array(bytes.buffer);
export function referenceCoast(x,z){const u=(x/12600+.5)*328,v=(z/8400+.5)*218;if(u<0||v<0||u>=328||v>=218)return -500;const a=Math.floor(u),b=Math.floor(v),fx=u-a,fz=v-b,i=b*329+a;return (grid[i]*(1-fx)+grid[i+1]*fx)*(1-fz)+(grid[i+329]*(1-fx)+grid[i+330]*fx)*fz;}
